<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $sale = App\Models\Sale::latest()->first(); if(!$sale) { echo "No sale found"; exit; } echo "Sale ID: {$sale->id} Type: {$sale->type} Warehouse: {$sale->warehouse_id}\n"; $sm = App\Models\StockMovement::where("ref_type", "sale")->where("ref_id", $sale->id)->get(); echo "Stock Movements: {$sm->count()}\n"; foreach($sm as $m) echo "Product: {$m->product_id} QtyOut: {$m->qty_out}\n";
